<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $workLocation->name }} - Checador</title><style>body{margin:0;background:#071b3d;color:#fff;font-family:Arial,sans-serif;display:grid;place-items:center;min-height:100vh;text-align:center}.box{background:#fff;color:#102040;padding:35px;border-radius:24px;box-shadow:0 15px 50px #0008;min-width:420px}h1{margin-top:0}.qr{display:flex;justify-content:center;margin:25px}.status{font-size:1.2rem}.count{font-size:2rem;font-weight:bold;color:#0762eb}</style></head><body><div class="box"><h1>{{ $workLocation->name }}</h1><p>Abre la app de RRHH y escanea este código</p><div id="qr" class="qr"></div><div class="status">El código cambia automáticamente en <span id="count" class="count">60</span> s</div><p id="error" style="color:#b00020"></p></div><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>let expires=0;async function refresh(){try{const r=await fetch(@json(route('work-locations.station-token',$workLocation)),{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('No se pudo renovar el QR');const d=await r.json();document.getElementById('qr').innerHTML='';new QRCode(document.getElementById('qr'),{text:d.token,width:320,height:320,correctLevel:QRCode.CorrectLevel.H});expires=new Date(d.expires_at).getTime();document.getElementById('error').textContent='';}catch(e){document.getElementById('error').textContent=e.message;}}setInterval(()=>{const s=Math.max(0,Math.ceil((expires-Date.now())/1000));document.getElementById('count').textContent=s;if(s===0)refresh();},1000);refresh();</script></body></html>
